    car_patches = image_patch.find("car")
    if len(car_patches) < 2:
        return "No second car found."

    sorted_cars = sorted(car_patches, key=lambda car: car.left + (car.right - car.left) / 2)
    middle_car = sorted_cars[len(sorted_cars) // 2]

    next_car = sorted_cars[min(len(sorted_cars) - 1, len(sorted_cars) // 2 + 1)]

    distance_to_next_car = abs(middle_car.left - next_car.left)

    if distance_to_next_car > 0:
        return f"The middle car is {distance_to_next_car} pixels behind another car."
    else:
        return "The middle car is directly behind another car."

